import java.time.Duration;
import java.time.Instant;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
class TokenBlacklistService {

    private static final String KEY_PREFIX = "auth:blacklist:";

    private final StringRedisTemplate redisTemplate;

    TokenBlacklistService(StringRedisTemplate redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    void blacklist(String rawToken, Instant expiresAt) {
        Duration ttl = Duration.between(Instant.now(), expiresAt);
        if (ttl.isNegative() || ttl.isZero()) {
            return; // token đã tự hết hạn, không cần blacklist nữa
        }
        redisTemplate.opsForValue().set(KEY_PREFIX + hash(rawToken), "revoked", ttl);
    }

    boolean isBlacklisted(String rawToken) {
        return Boolean.TRUE.equals(redisTemplate.hasKey(KEY_PREFIX + hash(rawToken)));
    }

    private String hash(String rawToken) {
        // TODO: băm rawToken bằng MessageDigest.getInstance("SHA-256"), encode
        // kết quả (byte[]) sang chuỗi hex, và trả về chuỗi đó - KHÔNG trả về
        // rawToken nguyên văn (mẫu này tạm return rawToken để minh hoạ luồng gọi).
        return rawToken;
    }
}

class BlacklistCheckFilter extends org.springframework.web.filter.OncePerRequestFilter {

    private final TokenBlacklistService blacklistService;

    BlacklistCheckFilter(TokenBlacklistService blacklistService) {
        this.blacklistService = blacklistService;
    }

    @Override
    protected void doFilterInternal(jakarta.servlet.http.HttpServletRequest request,
            jakarta.servlet.http.HttpServletResponse response,
            jakarta.servlet.FilterChain chain) throws jakarta.servlet.ServletException, java.io.IOException {
        String authHeader = request.getHeader("Authorization");
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            String rawToken = authHeader.substring(7);
            if (blacklistService.isBlacklisted(rawToken)) {
                response.sendError(jakarta.servlet.http.HttpServletResponse.SC_UNAUTHORIZED, "Token da bi thu hoi");
                return;
            }
        }
        chain.doFilter(request, response);
    }
}

// Phương án (a) trong ba phương án nêu ở khối phía trên: đăng ký filter này
// TRƯỚC bước xác thực token của dự án. Với cấu hình oauth2ResourceServer().jwt()
// như Day 22, mốc đó là BearerTokenAuthenticationFilter:
