import java.time.Duration;
import java.util.UUID;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
class RefreshTokenService {

    private static final String KEY_PREFIX = "auth:refresh:";
    private static final Duration REFRESH_TTL = Duration.ofDays(7);

    private final StringRedisTemplate redisTemplate;

    RefreshTokenService(StringRedisTemplate redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    String issue(Long userId) {
        String refreshToken = UUID.randomUUID().toString();
        redisTemplate.opsForValue().set(KEY_PREFIX + refreshToken, userId.toString(), REFRESH_TTL);
        return refreshToken;
    }

    Long rotate(String oldRefreshToken) {
        // TODO: đọc userId từ key KEY_PREFIX + oldRefreshToken; nếu không tồn
        // tại (null), coi là refresh token bị tái sử dụng/không hợp lệ - ném
        // một exception nghiệp vụ, KHÔNG issue token mới.
        // Nếu tồn tại: XOÁ ngay bản ghi cũ (redisTemplate.delete(...)) trước
        // khi trả về userId cho tầng gọi tự issue(...) một cặp access/refresh
        // token mới - thứ tự xoá-trước-issue-sau đảm bảo tính single-use.
        return null;
    }
}

@RestController
@RequestMapping("/api/orders")
class OrderController {

    // Mẫu này áp dụng lại @PreAuthorize("hasRole(...)") đã học ở Day 23.
    @PreAuthorize("hasRole('ADMIN')")
    @GetMapping
    List<OrderDto> findAll() {
        // TODO: trả về toàn bộ đơn hàng - chỉ ADMIN mới được phép xem toàn hệ thống.
        return null;
    }

    // Kiến trúc CHUẨN của khoá học (xem Day 33): hệ thống tự phát hành JWT ở
    // bước Login (Register -> mã hoá mật khẩu -> persist; Login ->
    // AuthenticationManager -> DaoAuthenticationProvider -> JwtEncoder phát
    // hành JWT có chữ ký). LÚC LOGIN, DaoAuthenticationProvider trả về một
    // Authentication có principal là UserDetails tuỳ chỉnh (CustomUserDetails,
    // id lấy từ bản ghi User đã persist trong Register) - nhưng Authentication
    // này chỉ tồn tại TẠM THỜI để xây JwtClaimsSet (sub = id người dùng, cộng
    // thêm một claim tuỳ chỉnh ví dụ "roles" chứa ROLE_CUSTOMER/ROLE_ADMIN).
    //
    // Ở MỖI request sau đó mang Bearer JWT, JwtAuthenticationProvider của
    // Resource Server xác thực chữ ký/exp rồi trả về JwtAuthenticationToken có
    // principal là một đối tượng Jwt (mặc định của framework) - KHÔNG phải
    // UserDetails được nạp lại từ DB. Vì vậy id người dùng hiện tại lấy qua
    // authentication.principal.subject (chính là claim sub đã nhúng vào JWT
    // lúc phát hành) - một giá trị server tự suy ra từ Authentication, KHÔNG
    // lấy từ path/body mà client tự gửi; quyền ROLE_CUSTOMER/ROLE_ADMIN lấy từ
    // claim "roles" qua một JwtAuthenticationConverter tuỳ chỉnh cấu hình ở
    // Day 33 (mặc định JwtAuthenticationProvider đọc claim scope thành
    // SCOPE_*, dự án đổi lại để nhất quán với tiền tố ROLE_ đã học ở Day 23).
    // Đây là hướng duy nhất Lab 8 chấm điểm.
    //
    // Phương án thay thế (chỉ khi dự án cấu hình oauth2ResourceServer() để xác
    // thực token do MỘT AUTHORIZATION SERVER BÊN NGOÀI phát hành, không phải
    // hệ thống tự phát hành ở Login - nhấn mạnh đây là lựa chọn kiến trúc được
    // gắn nhãn rõ ràng, KHÔNG phải mặc định của dự án, xem Day 33): principal
    // vẫn là một Jwt như trên, nhưng authorization server bên ngoài thường
    // không nhúng sẵn claim "roles" theo quy ước của dự án - lúc đó quyền
    // thường lấy theo claim scope mặc định (hasAuthority('SCOPE_...')) thay vì
    // hasRole(...), tuỳ cấu hình cụ thể của authorization server đó.
    // CHƯA CHỐT: điều kiện so khớp "#userId...equals(authentication.principal.subject)"
    // dưới đây là minh hoạ; tài liệu tham khảo của Day 23/24 chưa xác nhận đây
    // là cú pháp SpEL đúng để đọc thuộc tính tuỳ ý trên một đối tượng principal
    // tuỳ chỉnh (Jwt) bên trong @PreAuthorize - xem day24-blk-5. Phần
    // hasRole('CUSTOMER') vẫn là điều kiện chấm bắt buộc, áp dụng đúng mẫu đã
    // học ở Day 23.
    @PreAuthorize("hasRole('CUSTOMER') and #userId.toString().equals(authentication.principal.subject)")
    @GetMapping("/user/{userId}")
    List<OrderDto> findByUser(@PathVariable Long userId) {
        // TODO: trả về đơn hàng của đúng userId trong path - điều kiện SpEL ở
        // @PreAuthorize đã đảm bảo #userId khớp id của chính CUSTOMER đang đăng
        // nhập; không tự thêm kiểm tra userId lần hai trong thân method.
        return null;
    }
}

